package com.vignesh.banking.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.security.Key;import java.util.*;
@Service public class JwtService{ @Value("${app.jwt.secret}") private String secret; @Value("${app.jwt.expiration-ms}") private long exp; private Key key(){return Keys.hmacShaKeyFor(secret.getBytes());} private Claims claims(String t){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key()).build().parseSignedClaims(t).getPayload();} public String generate(String email,String role){return Jwts.builder().subject(email).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+exp)).signWith(key()).compact();} public String extractEmail(String t){return claims(t).getSubject();} public String extractRole(String t){Object r=claims(t).get("role"); return r==null?"CUSTOMER":r.toString();} public boolean valid(String t){try{claims(t);return true;}catch(Exception e){return false;}} }
